import{_ as o,l as s,o as e,c,v as t,p as l,x as i,d as n,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"牺牲缓存","description":"","frontmatter":{"title":"牺牲缓存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/victim-cache.md","filePath":"cs/victim-cache.md","lastUpdated":1789023840000}'),h={name:"cs/victim-cache.md"};function m(A,a,u,f,_,E){const r=s("Mermaid");return e(),c("div",null,[a[1]||(a[1]=t('<h1 id="牺牲缓存" tabindex="-1">牺牲缓存 <a class="header-anchor" href="#牺牲缓存" aria-label="Permalink to &quot;牺牲缓存&quot;">​</a></h1><div class="epigraph"><p>从 L1 踢出的行先掉进一块全相联小缓冲；马上又要用到的冲突受害者在这里命中，不必去 L2。</p><footer>—— 据 Jouppi, Improving Direct-Mapped Cache Performance by the Addition of a Small Fully-Associative Cache and Prefetch Buffers, ISCA 1990 整理</footer></div><p><a href="/cs/way-prediction">上一课</a> 在多路上省能量。<a href="/cs/cache-miss-types">缺失类型</a> 里冲突缺失是「容量本够、但索引互踢」。直接映射面积小、延迟低，冲突却狠。本课不重猜 way。缺口是 Jouppi 的<strong>牺牲缓存（victim cache）</strong>：替换出去的行在门口再留一晚。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两个经常交替使用的行若索引相同，直接映射会颠簸：每次命中都伴随着另一次缺失。加路能解，但延迟与功耗上升。缺口不是 RRIP（那是组内插入策略），而是<strong>在主 cache 旁边放 4–16 项全相联缓冲，专收刚被踢的行</strong>。</p><p><span class="marginnote">Jouppi 1990 同时提出 stream buffer。牺牲缓存打冲突，stream buffer 打强制/顺序，后课步长预取会接到流上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>L1 缺失：先 CAM 牺牲缓存。命中则与 L1 该组的牺牲者换位（swap），计为 L1 级命中的一种。未命中才去 L2。L1 替换：被踢行写入牺牲缓存（可能再踢牺牲缓存的 LRU）。</p>',8)),(e(),l(d,null,{default:i(()=>[p(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20MISS%5B%22L1%20%E7%BC%BA%E5%A4%B1%22%5D%20--%3E%20VIC%5B%22CAM%20%E7%89%BA%E7%89%B2%E7%BC%93%E5%AD%98%22%5D%0A%20%20VIC%20--%3E%7C%22%E5%91%BD%E4%B8%AD%22%7C%20SWAP%5B%22%E4%B8%8E%20L1%20%E8%AF%A5%E8%A1%8C%E4%BA%A4%E6%8D%A2%22%5D%0A%20%20VIC%20--%3E%7C%22%E7%BC%BA%E5%A4%B1%22%7C%20L2%5B%22%E8%AE%BF%E9%97%AE%20L2%22%5D%0A%20%20REPL%5B%22L1%20%E6%9B%BF%E6%8D%A2%22%5D%20--%3E%20VIC%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>冲突缺失被局部化：工作集只是「同一索引上的两三个热块」时，小 fully-assoc 足够。容量缺失帮不上——牺牲缓存装不下大工作集。它对 VIPT 几何友好：不必为冲突去加路、从而不必打破页内索引约束。</p><p>与 <a href="/cs/lru-plru">PLRU</a>：主 cache 仍按自己的替换走；牺牲缓存有独立的 LRU。两者不要当成一个大组相联来分析 Belady，除非你把它们模型化成 inclusive 旁路。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 LLC 的 victim 路径（有的目录把踢出的脏行写向 memory-side cache）全部展开。也不把预取缓冲与牺牲缓存混用：一个是未来块，一个是过去块。MLP 下一课：多个缺失同时在飞，与牺牲缓存正交。</p><p>后课默认：直接映射 + 小 victim 是合法的 L1 方案。真正拉开 CPI 的是同时悬着几趟 DRAM，不是再抠一次冲突。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>牺牲缓存用全相联小缓冲接住刚踢出的冲突受害者。</li><li>对容量缺失无效；与流预取分工不同。</li><li>同时悬着的缺失条数是下一课 MLP。</li><li>出处：Jouppi, <em>ISCA</em>, 1990。</li></ul>',8))])}const L=o(h,[["render",m]]);export{B as __pageData,L as default};
